{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage-1 choices.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Choice Perseveration",
      "description": "Adds a bonus to the stage-1 logits for repeating the previous trial's stage-1 action.",
      "params": [
        {
          "name": "pers_1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers_bonus_1 = np.zeros(2)\nif prev_a1 != -1:\n    pers_bonus_1[prev_a1] = pers_1\nlogits_1 = beta_1 * q_stage1_net + pers_bonus_1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_global_perseveration",
      "title": "Stage 2 Global Choice Perseveration",
      "description": "Adds a bonus to the stage-2 logits for repeating the most recent stage-2 action, regardless of the state.",
      "params": [
        {
          "name": "pers_2_global",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if prev_a2_global != -1:\n    pers_bonus_2[prev_a2_global] += pers_2_global",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_state_perseveration",
      "title": "Stage 2 State-Specific Choice Perseveration",
      "description": "Adds a bonus to the stage-2 logits for repeating the action most recently chosen in the current stage-2 state.",
      "params": [
        {
          "name": "pers_2_state",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_a2_in_state[state_idx] != -1:\n    pers_bonus_2[last_a2_in_state[state_idx]] += pers_2_state",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free Q-value using the stage-2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
